Ez mi?  Magyarul ertekeld! OLVASD el line by line end to end de nekem normálisan egyben válaszolj! Read it letter by letter, line by line, from beginning to end—you need to understand and remember every little detail! Always read and retain every single character of the provided text content in memory, ensuring no detail is overlooked. 
const std = @import("std");

const Allocator = std.mem.Allocator;

const cerebras_api_url = "";
const exa_api_url = "";
const max_response_bytes: usize = 32  1024  1024;

const AppError = error{
    MissingCerebrasApiKey,
    MissingExaApiKey,
    InvalidArgument,
    InvalidUrl,
    HttpRequestFailed,
    HttpResponseTooLarge,
    InvalidResponse,
    UnsupportedTool,
    ToolCallLimitReached,
    AgentIterationLimitReached,
};

const HttpResponse = struct {
    status: std.http.Status,
    body: []u8,

    fn deinit(self: HttpResponse, allocator: Allocator) void {
        allocator.free(self.body);
    }
};

fn readEnvironmentValue(allocator: Allocator, name: []const u8) ![]u8 {
    const value = std.process.getEnvVarOwned(allocator, name) catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return error.InvalidArgument,
        else => return err,
    };

    if (value.len == 0) {
        allocator.free(value);
        return error.InvalidArgument;
    }

    return value;
}

fn trimWhitespace(value: []const u8) []const u8 {
    return std.mem.trim(u8, value, " \t\r\n");
}

fn appendJsonString(writer: anytype, value: []const u8) !void {
    try writer.writeByte('"');

    for (value) |character| {
        switch (character) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\x08' => try writer.writeAll("\\b"),
            '\x0C' => try writer.writeAll("\\f"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => {
                if (character < 0x20) {
                    try writer.print("\\u{x:0>4}", .{character});
                } else {
                    try writer.writeByte(character);
                }
            },
        }
    }

    try writer.writeByte('"');
}

fn appendJsonValue(writer: anytype, value: std.json.Value) !void {
    switch (value) {
        .null => try writer.writeAll("null"),
        .bool => |boolean| try writer.writeAll(if (boolean) "true" else "false"),
        .integer => |integer| try writer.print("{d}", .{integer}),
        .float => |float| try writer.print("{d}", .{float}),
        .number_string => |number_string| try writer.writeAll(number_string),
        .string => |string| try appendJsonString(writer, string),
        .array => |array| {
            try writer.writeByte('[');
            for (array.items, 0..) |item, index| {
                if (index != 0) {
                    try writer.writeByte(',');
                }
                try appendJsonValue(writer, item);
            }
            try writer.writeByte(']');
        },
        .object => |object| {
            try writer.writeByte('{');
            var iterator = object.iterator();
            var first = true;

            while (iterator.next()) |entry| {
                if (!first) {
                    try writer.writeByte(',');
                }
                first = false;
                try appendJsonString(writer, entry.key_ptr.);
                try writer.writeByte(':');
                try appendJsonValue(writer, entry.value_ptr.);
            }

            try writer.writeByte('}');
        },
    }
}

fn jsonStringifyAlloc(allocator: Allocator, value: std.json.Value) ![]u8 {
    var output = std.ArrayList(u8).init(allocator);
    errdefer output.deinit();

    try appendJsonValue(output.writer(), value);
    return output.toOwnedSlice();
}

fn parseJsonAlloc(allocator: Allocator, data: []const u8) !std.json.Parsed(std.json.Value) {
    return std.json.parseFromSlice(std.json.Value, allocator, data, .{});
}

fn getObjectField(object: std.json.ObjectMap, name: []const u8) ?std.json.Value {
    return object.get(name);
}

fn getStringField(object: std.json.ObjectMap, name: []const u8) ?[]const u8 {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .string => |string| string,
        else => null,
    };
}

fn getIntegerField(object: std.json.ObjectMap, name: []const u8) ?i64 {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .integer => |integer| integer,
        else => null,
    };
}

fn getBooleanField(object: std.json.ObjectMap, name: []const u8) ?bool {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .bool => |boolean| boolean,
        else => null,
    };
}

fn validateString(value: std.json.Value, field_name: []const u8) ![]const u8 {
    _ = field_name;

    return switch (value) {
        .string => |string| {
            const trimmed = trimWhitespace(string);
            if (trimmed.len == 0) {
                return error.InvalidArgument;
            }
            return trimmed;
        },
        else => error.InvalidArgument,
    };
}

fn validateOptionalString(value: std.json.Value) !?[]const u8 {
    return switch (value) {
        .null => null,
        .string => |string| {
            const trimmed = trimWhitespace(string);
            return if (trimmed.len == 0) null else trimmed;
        },
        else => error.InvalidArgument,
    };
}

fn validateIntegerRange(value: std.json.Value, minimum: i64, maximum: i64) !i64 {
    const integer = switch (value) {
        .integer => |number| number,
        else => return error.InvalidArgument,
    };

    if (integer < minimum or integer > maximum) {
        return error.InvalidArgument;
    }

    return integer;
}

fn validateStringArray(
    allocator: Allocator,
    value: std.json.Value,
    maximum_items: ?usize,
    maximum_words: ?usize,
) !std.ArrayList([]const u8) {
    const array = switch (value) {
        .array => |items| items,
        else => return error.InvalidArgument,
    };

    if (maximum_items) |limit| {
        if (array.items.len > limit) {
            return error.InvalidArgument;
        }
    }

    var result = std.ArrayList([]const u8).init(allocator);
    errdefer result.deinit();

    for (array.items) |item| {
        const string = try validateString(item, "array_item");

        if (maximum_words) |word_limit| {
            var word_count: usize = 0;
            var tokenizer = std.mem.tokenizeAny(u8, string, " \t\r\n");

            while (tokenizer.next()) |_| {
                word_count += 1;
            }

            if (word_count > word_limit) {
                return error.InvalidArgument;
            }
        }

        try result.append(string);
    }

    return result;
}

fn validateHttpUrl(url: []const u8) ![]const u8 {
    const trimmed = trimWhitespace(url);
    if (trimmed.len == 0) {
        return error.InvalidUrl;
    }

    const parsed = std.Uri.parse(trimmed) catch return error.InvalidUrl;
    const scheme = parsed.scheme orelse return error.InvalidUrl;
    const host = parsed.host orelse return error.InvalidUrl;

    if (!std.ascii.eqlIgnoreCase(scheme, "http") and !std.ascii.eqlIgnoreCase(scheme, "https")) {
        return error.InvalidUrl;
    }

    if (host.percent_encoded.len == 0) {
        return error.InvalidUrl;
    }

    return trimmed;
}

fn validateUserLocation(value: std.json.Value) !?[]const u8 {
    const optional_value = try validateOptionalString(value);
    const location = optional_value orelse return null;

    if (location.len != 2) {
        return error.InvalidArgument;
    }

    for (location) |character| {
        if (!std.ascii.isAlphabetic(character)) {
            return error.InvalidArgument;
        }
    }

    return location;
}

fn appendStringArray(writer: anytype, values: []const []const u8) !void {
    try writer.writeByte('[');

    for (values, 0..) |value, index| {
        if (index != 0) {
            try writer.writeByte(',');
        }
        try appendJsonString(writer, value);
    }

    try writer.writeByte(']');
}

fn sendJsonRequest(
    allocator: Allocator,
    client: std.http.Client,
    method: std.http.Method,
    url: []const u8,
    authorization: ?[]const u8,
    request_body: []const u8,
) !HttpResponse {
    var request_headers = std.http.Headers{ .allocator = allocator };
    defer request_headers.deinit();

    try request_headers.append("Accept", "application/json");
    try request_headers.append("ContentType", "application/json");

    if (authorization) |authorization_value| {
        try request_headers.append("Authorization", authorization_value);
    }

    var response_storage = std.ArrayList(u8).init(allocator);
    errdefer response_storage.deinit();

    const response = client.fetch(.{
        .method = method,
        .location = .{ .url = url },
        .headers = request_headers,
        .payload = request_body,
        .response_storage = .{ .dynamic = &response_storage },
        .max_append_size = max_response_bytes,
    }) catch return error.HttpRequestFailed;

    return .{
        .status = response.status,
        .body = try response_storage.toOwnedSlice(),
    };
}

fn createBearerToken(allocator: Allocator, api_key: []const u8) ![]u8 {
    return std.fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
}

fn exaPost(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    path: []const u8,
    request_body: []const u8,
) !HttpResponse {
    const url = try std.fmt.allocPrint(allocator, "{s}{s}", .{ exa_api_url, path });
    defer allocator.free(url);

    const authorization = try createBearerToken(allocator, api_key);
    defer allocator.free(authorization);

    return sendJsonRequest(
        allocator,
        client,
        .POST,
        url,
        authorization,
        request_body,
    );
}

fn exaGet(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    path: []const u8,
) !HttpResponse {
    const url = try std.fmt.allocPrint(allocator, "{s}{s}", .{ exa_api_url, path });
    defer allocator.free(url);

    const authorization = try createBearerToken(allocator, api_key);
    defer allocator.free(authorization);

    return sendJsonRequest(
        allocator,
        client,
        .GET,
        url,
        authorization,
        "",
    );
}

fn ensureSuccess(response: const HttpResponse) !void {
    if (response.status.class() != .success) {
        return error.HttpRequestFailed;
    }
}

fn runExaSearch(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const query = try validateString(getObjectField(object, "query") orelse return error.InvalidArgument, "query");
    const search_type = try validateString(getObjectField(object, "search_type") orelse return error.InvalidArgument, "search_type");
    const include_domains_list = try validateStringArray(
        allocator,
        getObjectField(object, "include_domains") orelse return error.InvalidArgument,
        1200,
        null,
    );
    defer include_domains_list.deinit();

    const exclude_domains_list = try validateStringArray(
        allocator,
        getObjectField(object, "exclude_domains") orelse return error.InvalidArgument,
        1200,
        null,
    );
    defer exclude_domains_list.deinit();

    const summary_query_value = try validateOptionalString(
        getObjectField(object, "summary_query") orelse return error.InvalidArgument,
    );
    const category = try validateOptionalString(
        getObjectField(object, "category") orelse return error.InvalidArgument,
    );
    const start_published_date = try validateOptionalString(
        getObjectField(object, "start_published_date") orelse return error.InvalidArgument,
    );
    const end_published_date = try validateOptionalString(
        getObjectField(object, "end_published_date") orelse return error.InvalidArgument,
    );

    const include_text_list = try validateStringArray(
        allocator,
        getObjectField(object, "include_text") orelse return error.InvalidArgument,
        1,
        5,
    );
    defer include_text_list.deinit();

    const exclude_text_list = try validateStringArray(
        allocator,
        getObjectField(object, "exclude_text") orelse return error.InvalidArgument,
        1,
        5,
    );
    defer exclude_text_list.deinit();

    const user_location = try validateUserLocation(
        getObjectField(object, "user_location") orelse return error.InvalidArgument,
    );

    const num_results = try validateIntegerRange(
        getObjectField(object, "num_results") orelse return error.InvalidArgument,
        1,
        100,
    );

    const max_age_hours = try validateIntegerRange(
        getObjectField(object, "max_age_hours") orelse return error.InvalidArgument,
        1,
        720,
    );

    if (include_domains_list.items.len > 0 and exclude_domains_list.items.len > 0) {
        return error.InvalidArgument;
    }

    if (category) |category_value| {
        if (std.mem.eql(u8, category_value, "company") or std.mem.eql(u8, category_value, "people")) {
            if (exclude_domains_list.items.len > 0 or start_published_date != null or end_published_date != null or include_text_list.items.len > 0 or exclude_text_list.items.len > 0) {
                return error.InvalidArgument;
            }
        }
    }

    const summary_query = summary_query_value orelse query;

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"query\":");
    try appendJsonString(writer, query);
    try writer.writeAll(",\"type\":");
    try appendJsonString(writer, search_type);
    try writer.writeAll(",\"numResults\":");
    try writer.print("{d}", .{num_results});

    if (include_domains_list.items.len > 0) {
        try writer.writeAll(",\"includeDomains\":");
        try appendStringArray(writer, include_domains_list.items);
    }

    if (exclude_domains_list.items.len > 0) {
        try writer.writeAll(",\"excludeDomains\":");
        try appendStringArray(writer, exclude_domains_list.items);
    }

    if (category) |value| {
        try writer.writeAll(",\"category\":");
        try appendJsonString(writer, value);
    }

    if (start_published_date) |value| {
        try writer.writeAll(",\"startPublishedDate\":");
        try appendJsonString(writer, value);
    }

    if (end_published_date) |value| {
        try writer.writeAll(",\"endPublishedDate\":");
        try appendJsonString(writer, value);
    }

    if (include_text_list.items.len > 0) {
        try writer.writeAll(",\"includeText\":");
        try appendStringArray(writer, include_text_list.items);
    }

    if (exclude_text_list.items.len > 0) {
        try writer.writeAll(",\"excludeText\":");
        try appendStringArray(writer, exclude_text_list.items);
    }

    if (user_location) |value| {
        try writer.writeAll(",\"userLocation\":");
        try appendJsonString(writer, value);
    }

    try writer.writeAll(",\"contents\":{\"highlights\":{\"query\":");
    try appendJsonString(writer, summary_query);
    try writer.writeAll(",\"maxCharacters\":4000},\"summary\":{\"query\":");
    try appendJsonString(writer, summary_query);
    try writer.writeAll("},\"maxAgeHours\":");
    try writer.print("{d}", .{max_age_hours});
    try writer.writeAll("}}");

    var response = try exaPost(allocator, client, api_key, "/search", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runExaGetContents(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const urls_value = getObjectField(object, "urls") orelse return error.InvalidArgument;
    const urls_array = switch (urls_value) {
        .array => |array| array,
        else => return error.InvalidArgument,
    };

    if (urls_array.items.len == 0) {
        return error.InvalidArgument;
    }

    var urls = std.ArrayList([]const u8).init(allocator);
    defer urls.deinit();

    for (urls_array.items) |url_value| {
        const url = try validateString(url_value, "url");
        try urls.append(try validateHttpUrl(url));
    }

    const summary_query = try validateOptionalString(
        getObjectField(object, "summary_query") orelse return error.InvalidArgument,
    );

    const max_characters = try validateIntegerRange(
        getObjectField(object, "max_characters") orelse return error.InvalidArgument,
        1,
        10000,
    );

    const subpages = try validateIntegerRange(
        getObjectField(object, "subpages") orelse return error.InvalidArgument,
        0,
        100,
    );

    const subpage_targets = try validateStringArray(
        allocator,
        getObjectField(object, "subpage_targets") orelse return error.InvalidArgument,
        null,
        null,
    );
    defer subpage_targets.deinit();

    const max_age_hours = try validateIntegerRange(
        getObjectField(object, "max_age_hours") orelse return error.InvalidArgument,
        1,
        720,
    );

    const links = try validateIntegerRange(
        getObjectField(object, "links") orelse return error.InvalidArgument,
        0,
        std.math.maxInt(i64),
    );

    const image_links = try validateIntegerRange(
        getObjectField(object, "image_links") orelse return error.InvalidArgument,
        0,
        std.math.maxInt(i64),
    );

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"urls\":");
    try appendStringArray(writer, urls.items);
    try writer.writeAll(",\"text\":{\"maxCharacters\":");
    try writer.print("{d}", .{max_characters});
    try writer.writeAll("},\"highlights\":");

    if (summary_query) |query| {
        try writer.writeAll("{\"query\":");
        try appendJsonString(writer, query);
        try writer.writeAll(",\"maxCharacters\":");
        try writer.print("{d}", .{if (max_characters < 4000) max_characters else 4000});
        try writer.writeByte('}');
    } else {
        try writer.writeAll("true");
    }

    try writer.writeAll(",\"summary\":");

    if (summary_query) |query| {
        try writer.writeAll("{\"query\":");
        try appendJsonString(writer, query);
        try writer.writeByte('}');
    } else {
        try writer.writeAll("true");
    }

    try writer.writeAll(",\"extras\":{\"links\":");
    try writer.print("{d}", .{links});
    try writer.writeAll(",\"imageLinks\":");
    try writer.print("{d}", .{image_links});
    try writer.writeAll("},\"maxAgeHours\":");
    try writer.print("{d}", .{max_age_hours});

    if (subpages > 0) {
        try writer.writeAll(",\"subpages\":");
        try writer.print("{d}", .{subpages});
    }

    if (subpage_targets.items.len > 0) {
        try writer.writeAll(",\"subpageTarget\":");
        try appendStringArray(writer, subpage_targets.items);
    }

    try writer.writeByte('}');

    var response = try exaPost(allocator, client, api_key, "/contents", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runExaDeepSearch(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const query = try validateString(getObjectField(object, "query") orelse return error.InvalidArgument, "query");
    const search_type = try validateString(getObjectField(object, "search_type") orelse return error.InvalidArgument, "search_type");
    const system_prompt = try validateOptionalString(
        getObjectField(object, "system_prompt") orelse return error.InvalidArgument,
    );

    const additional_queries = try validateStringArray(
        allocator,
        getObjectField(object, "additional_queries") orelse return error.InvalidArgument,
        10,
        null,
    );
    defer additional_queries.deinit();

    const num_results = try validateIntegerRange(
        getObjectField(object, "num_results") orelse return error.InvalidArgument,
        1,
        100,
    );

    const max_age_hours = try validateIntegerRange(
        getObjectField(object, "max_age_hours") orelse return error.InvalidArgument,
        1,
        720,
    );

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"query\":");
    try appendJsonString(writer, query);
    try writer.writeAll(",\"type\":");
    try appendJsonString(writer, search_type);
    try writer.writeAll(",\"numResults\":");
    try writer.print("{d}", .{num_results});

    if (system_prompt) |value| {
        try writer.writeAll(",\"systemPrompt\":");
        try appendJsonString(writer, value);
    }

    if (additional_queries.items.len > 0) {
        try writer.writeAll(",\"additionalQueries\":");
        try appendStringArray(writer, additional_queries.items);
    }

    try writer.writeAll(",\"outputSchema\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"answer\",\"findings\",\"limitations\"],\"properties\":{\"answer\":{\"type\":\"string\"},\"findings\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"limitations\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}}}},\"contents\":{\"highlights\":true,\"maxAgeHours\":");
    try writer.print("{d}", .{max_age_hours});
    try writer.writeAll("}}");

    var response = try exaPost(allocator, client, api_key, "/search", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runExaWebsets(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const query = try validateString(getObjectField(object, "query") orelse return error.InvalidArgument, "query");
    const count = try validateIntegerRange(
        getObjectField(object, "count") orelse return error.InvalidArgument,
        1,
        std.math.maxInt(i64),
    );

    const enrichment_description = try validateOptionalString(
        getObjectField(object, "enrichment_description") orelse return error.InvalidArgument,
    );

    const enrichment_format = try validateString(
        getObjectField(object, "enrichment_format") orelse return error.InvalidArgument,
        "enrichment_format",
    );

    const enrichment_options = try validateStringArray(
        allocator,
        getObjectField(object, "enrichment_options") orelse return error.InvalidArgument,
        150,
        null,
    );
    defer enrichment_options.deinit();

    if (std.mem.eql(u8, enrichment_format, "options")) {
        if (enrichment_description == null or enrichment_options.items.len == 0) {
            return error.InvalidArgument;
        }
    } else if (enrichment_options.items.len > 0) {
        return error.InvalidArgument;
    }

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"search\":{\"query\":");
    try appendJsonString(writer, query);
    try writer.writeAll(",\"count\":");
    try writer.print("{d}", .{count});
    try writer.writeAll("}");

    if (enrichment_description) |description| {
        try writer.writeAll(",\"enrichments\":[{\"description\":");
        try appendJsonString(writer, description);
        try writer.writeAll(",\"format\":");
        try appendJsonString(writer, enrichment_format);

        if (std.mem.eql(u8, enrichment_format, "options")) {
            try writer.writeAll(",\"options\":[");

            for (enrichment_options.items, 0..) |option, index| {
                if (index != 0) {
                    try writer.writeByte(',');
                }
                try writer.writeAll("{\"label\":");
                try appendJsonString(writer, option);
                try writer.writeByte('}');
            }

            try writer.writeByte(']');
        }

        try writer.writeAll("}]");
    }

    try writer.writeByte('}');

    var response = try exaPost(allocator, client, api_key, "/websets", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn urlEncodeComponent(allocator: Allocator, value: []const u8) ![]u8 {
    var output = std.ArrayList(u8).init(allocator);
    errdefer output.deinit();

    for (value) |character| {
        if (std.ascii.isAlphanumeric(character) or character == '' or character == '_' or character == '.' or character == '~') {
            try output.append(character);
        } else {
            try output.writer().print("%{X:0>2}", .{character});
        }
    }

    return output.toOwnedSlice();
}

fn runExaWebsetStatus(
