fn runTool(
    allocator: Allocator,
    client: std.http.Client,
    exa_api_key: []const u8,
    function_name: []const u8,
    arguments_text: []const u8,
) ![]u8 {
    var parsed_arguments = try parseJsonAlloc(allocator, arguments_text);
    defer parsed_arguments.deinit();

    if (std.mem.eql(u8, function_name, "exa_search")) {
        return runExaSearch(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_get_contents")) {
        return runExaGetContents(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_deep_search")) {
        return runExaDeepSearch(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_websets")) {
        return runExaWebsets(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_webset_status")) {
        return runExaWebsetStatus(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_webset_items")) {
        return runExaWebsetItems(allocator, client, exa_api_key, parsed_arguments.value);
    }

    return error.UnsupportedTool;
}

