fn appendAssistantMessage(writer: anytype, message: std.json.Value) !void {
    const object = switch (message) {
        .object => |value| value,
        else => return error.InvalidResponse,
    };

    try writer.writeAll("{\"role\":\"assistant\"");

    if (getStringField(object, "content")) |content| {
        try writer.writeAll(",\"content\":");
        try appendJsonString(writer, content);
    } else {
        try writer.writeAll(",\"content\":null");
    }

    if (getObjectField(object, "tool_calls")) |tool_calls_value| {
        const tool_calls = switch (tool_calls_value) {
            .array => |value| value,
            else => return error.InvalidResponse,
        };

        if (tool_calls.items.len > 0) {
            try writer.writeAll(",\"tool_calls\":[");

            for (tool_calls.items, 0..) |tool_call_value, index| {
                if (index != 0) {
                    try writer.writeByte(',');
                }

                const tool_call = switch (tool_call_value) {
                    .object => |value| value,
                    else => return error.InvalidResponse,
                };

                const id = getStringField(tool_call, "id") orelse return error.InvalidResponse;
                const function_value = getObjectField(tool_call, "function") orelse return error.InvalidResponse;
                const function = switch (function_value) {
                    .object => |value| value,
                    else => return error.InvalidResponse,
                };

                const name = getStringField(function, "name") orelse return error.InvalidResponse;
                const arguments = getStringField(function, "arguments") orelse return error.InvalidResponse;

                try writer.writeAll("{\"id\":");
                try appendJsonString(writer, id);
                try writer.writeAll(",\"type\":\"function\",\"function\":{\"name\":");
                try appendJsonString(writer, name);
                try writer.writeAll(",\"arguments\":");
                try appendJsonString(writer, arguments);
                try writer.writeAll("}}");
            }

            try writer.writeByte(']');
        }
    }

    try writer.writeByte('}');
}

