fn appendStoredMessage(writer: anytype, message: StoredMessage) !void {
    switch (message) {
        .system => |content| try appendSystemMessage(writer),
        .user => |content| try appendUserMessage(writer, content),
        .assistant => |value| try appendAssistantMessage(writer, value),
        .tool => |value| try appendToolMessage(writer, value.tool_call_id, value.content),
