fn readEnvironmentValue(allocator: Allocator, name: []const u8) ![]u8 {
    const value = std.process.getEnvVarOwned(allocator, name) catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return error.InvalidArgument,
