fn validateString(value: std.json.Value, field_name: []const u8) ![]const u8 {
    _ = field_name;

    return switch (value) {
        .string => |string| {
            const trimmed = trimWhitespace(string);
            if (trimmed.len == 0) {
                return error.InvalidArgument;
            }
            return trimmed;
        },
        else => error.InvalidArgument,
    };
}

fn validateOptionalString(value: std.json.Value) !?[]const u8 {
    return switch (value) {
        .null => null,
        .string => |string| {
            const trimmed = trimWhitespace(string);
            return if (trimmed.len == 0) null else trimmed;
        },
        else => error.InvalidArgument,
    };
}

fn validateIntegerRange(value: std.json.Value, minimum: i64, maximum: i64) !i64 {
    const integer = switch (value) {
        .integer => |number| number,
        else => return error.InvalidArgument,
    };

    if (integer < minimum or integer > maximum) {
        return error.InvalidArgument;
    }

    return integer;
}

fn validateStringArray(
    allocator: Allocator,
    value: std.json.Value,
    maximum_items: ?usize,
    maximum_words: ?usize,
) !std.ArrayList([]const u8) {
    const array = switch (value) {
        .array => |items| items,
        else => return error.InvalidArgument,
    };

    if (maximum_items) |limit| {
        if (array.items.len > limit) {
            return error.InvalidArgument;
        }
    }

    var result = std.ArrayList([]const u8).init(allocator);
    errdefer result.deinit();

    for (array.items) |item| {
        const string = try validateString(item, "array_item");

        if (maximum_words) |word_limit| {
            var word_count: usize = 0;
            var tokenizer = std.mem.tokenizeAny(u8, string, " \t\r\n");

            while (tokenizer.next()) |_| {
                word_count += 1;
            }

            if (word_count > word_limit) {
                return error.InvalidArgument;
            }
        }

        try result.append(string);
    }

    return result;
}

fn validateHttpUrl(url: []const u8) ![]const u8 {
    const trimmed = trimWhitespace(url);
    if (trimmed.len == 0) {
        return error.InvalidUrl;
    }

    const parsed = std.Uri.parse(trimmed) catch return error.InvalidUrl;
    const scheme = parsed.scheme orelse return error.InvalidUrl;
    const host = parsed.host orelse return error.InvalidUrl;

    if (!std.ascii.eqlIgnoreCase(scheme, "http") and !std.ascii.eqlIgnoreCase(scheme, "https")) {
        return error.InvalidUrl;
    }

    if (host.percent_encoded.len == 0) {
        return error.InvalidUrl;
    }

    return trimmed;
}

fn validateUserLocation(value: std.json.Value) !?[]const u8 {
    const optional_value = try validateOptionalString(value);
    const location = optional_value orelse return null;

    if (location.len != 2) {
