fn sendJsonRequest(
    allocator: Allocator,
    client: std.http.Client,
    method: std.http.Method,
    url: []const u8,
    authorization: ?[]const u8,
    request_body: []const u8,
) !HttpResponse {
    var request_headers = std.http.Headers{ .allocator = allocator };
    defer request_headers.deinit();

    try request_headers.append("Accept", "application/json");
    try request_headers.append("ContentType", "application/json");

    if (authorization) |authorization_value| {
        try request_headers.append("Authorization", authorization_value);
    }

    var response_storage = std.ArrayList(u8).init(allocator);
    errdefer response_storage.deinit();

    const response = client.fetch(.{
        .method = method,
        .location = .{ .url = url },
        .headers = request_headers,
        .payload = request_body,
        .response_storage = .{ .dynamic = &response_storage },
        .max_append_size = max_response_bytes,
    }) catch return error.HttpRequestFailed;

    return .{
        .status = response.status,
        .body = try response_storage.toOwnedSlice(),
    };
}

