        client,
        .POST,
        url,
        authorization,
        request_body,
    );
}

fn exaGet(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    path: []const u8,
) !HttpResponse {
    const url = try std.fmt.allocPrint(allocator, "{s}{s}", .{ exa_api_url, path });
    defer allocator.free(url);

    const authorization = try createBearerToken(allocator, api_key);
    defer allocator.free(authorization);

    return sendJsonRequest(
        allocator,
        client,
        .GET,
        url,
        authorization,
        "",
    );
}

fn ensureSuccess(response: const HttpResponse) !void {
    if (response.status.class() != .success) {
        return error.HttpRequestFailed;
    }
}

fn runExaSearch(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const query = try validateString(getObjectField(object, "query") orelse return error.InvalidArgument, "query");
    const search_type = try validateString(getObjectField(object, "search_type") orelse return error.InvalidArgument, "search_type");
    const include_domains_list = try validateStringArray(
        allocator,
        getObjectField(object, "include_domains") orelse return error.InvalidArgument,
        1200,
        null,
    );
    defer include_domains_list.deinit();

    const exclude_domains_list = try validateStringArray(
        allocator,
        getObjectField(object, "exclude_domains") orelse return error.InvalidArgument,
        1200,
        null,
    );
    defer exclude_domains_list.deinit();

    const summary_query_value = try validateOptionalString(
        getObjectField(object, "summary_query") orelse return error.InvalidArgument,
    );
    const category = try validateOptionalString(
        getObjectField(object, "category") orelse return error.InvalidArgument,
    );
    const start_published_date = try validateOptionalString(
        getObjectField(object, "start_published_date") orelse return error.InvalidArgument,
    );
    const end_published_date = try validateOptionalString(
        getObjectField(object, "end_published_date") orelse return error.InvalidArgument,
    );

    const include_text_list = try validateStringArray(
        allocator,
        getObjectField(object, "include_text") orelse return error.InvalidArgument,
        1,
        5,
    );
    defer include_text_list.deinit();

    const exclude_text_list = try validateStringArray(
        allocator,
        getObjectField(object, "exclude_text") orelse return error.InvalidArgument,
        1,
        5,
    );
    defer exclude_text_list.deinit();

    const user_location = try validateUserLocation(
        getObjectField(object, "user_location") orelse return error.InvalidArgument,
    );

    const num_results = try validateIntegerRange(
        getObjectField(object, "num_results") orelse return error.InvalidArgument,
        1,
        100,
    );

    const max_age_hours = try validateIntegerRange(
        getObjectField(object, "max_age_hours") orelse return error.InvalidArgument,
        1,
        720,
    );

    if (include_domains_list.items.len > 0 and exclude_domains_list.items.len > 0) {
        return error.InvalidArgument;
    }

    if (category) |category_value| {
        if (std.mem.eql(u8, category_value, "company") or std.mem.eql(u8, category_value, "people")) {
            if (exclude_domains_list.items.len > 0 or start_published_date != null or end_published_date != null or include_text_list.items.len > 0 or exclude_text_list.items.len > 0) {
                return error.InvalidArgument;
            }
        }
    }

    const summary_query = summary_query_value orelse query;

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"query\":");
    try appendJsonString(writer, query);
    try writer.writeAll(",\"type\":");
    try appendJsonString(writer, search_type);
    try writer.writeAll(",\"numResults\":");
    try writer.print("{d}", .{num_results});

    if (include_domains_list.items.len > 0) {
        try writer.writeAll(",\"includeDomains\":");
        try appendStringArray(writer, include_domains_list.items);
    }

    if (exclude_domains_list.items.len > 0) {
        try writer.writeAll(",\"excludeDomains\":");
        try appendStringArray(writer, exclude_domains_list.items);
    }

    if (category) |value| {
        try writer.writeAll(",\"category\":");
        try appendJsonString(writer, value);
    }

    if (start_published_date) |value| {
        try writer.writeAll(",\"startPublishedDate\":");
        try appendJsonString(writer, value);
    }

    if (end_published_date) |value| {
        try writer.writeAll(",\"endPublishedDate\":");
        try appendJsonString(writer, value);
    }

    if (include_text_list.items.len > 0) {
        try writer.writeAll(",\"includeText\":");
        try appendStringArray(writer, include_text_list.items);
    }

    if (exclude_text_list.items.len > 0) {
        try writer.writeAll(",\"excludeText\":");
        try appendStringArray(writer, exclude_text_list.items);
    }

    if (user_location) |value| {
        try writer.writeAll(",\"userLocation\":");
        try appendJsonString(writer, value);
    }

    try writer.writeAll(",\"contents\":{\"highlights\":{\"query\":");
    try appendJsonString(writer, summary_query);
    try writer.writeAll(",\"maxCharacters\":4000},\"summary\":{\"query\":");
    try appendJsonString(writer, summary_query);
    try writer.writeAll("},\"maxAgeHours\":");
    try writer.print("{d}", .{max_age_hours});
    try writer.writeAll("}}");

    var response = try exaPost(allocator, client, api_key, "/search", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runExaGetContents(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const urls_value = getObjectField(object, "urls") orelse return error.InvalidArgument;
    const urls_array = switch (urls_value) {
        .array => |array| array,
        else => return error.InvalidArgument,
    };

    if (urls_array.items.len == 0) {
        return error.InvalidArgument;
    }

    var urls = std.ArrayList([]const u8).init(allocator);
    defer urls.deinit();

    for (urls_array.items) |url_value| {
        const url = try validateString(url_value, "url");
        try urls.append(try validateHttpUrl(url));
    }

    const summary_query = try validateOptionalString(
        getObjectField(object, "summary_query") orelse return error.InvalidArgument,
    );

    const max_characters = try validateIntegerRange(
        getObjectField(object, "max_characters") orelse return error.InvalidArgument,
        1,
        10000,
    );

    const subpages = try validateIntegerRange(
        getObjectField(object, "subpages") orelse return error.InvalidArgument,
        0,
        100,
    );

    const subpage_targets = try validateStringArray(
        allocator,
        getObjectField(object, "subpage_targets") orelse return error.InvalidArgument,
        null,
        null,
    );
    defer subpage_targets.deinit();

    const max_age_hours = try validateIntegerRange(
        getObjectField(object, "max_age_hours") orelse return error.InvalidArgument,
        1,
        720,
    );

    const links = try validateIntegerRange(
        getObjectField(object, "links") orelse return error.InvalidArgument,
        0,
        std.math.maxInt(i64),
    );

    const image_links = try validateIntegerRange(
        getObjectField(object, "image_links") orelse return error.InvalidArgument,
        0,
        std.math.maxInt(i64),
    );

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"urls\":");
    try appendStringArray(writer, urls.items);
    try writer.writeAll(",\"text\":{\"maxCharacters\":");
    try writer.print("{d}", .{max_characters});
    try writer.writeAll("},\"highlights\":");

    if (summary_query) |query| {
        try writer.writeAll("{\"query\":");
        try appendJsonString(writer, query);
        try writer.writeAll(",\"maxCharacters\":");
        try writer.print("{d}", .{if (max_characters < 4000) max_characters else 4000});
        try writer.writeByte('}');
    } else {
        try writer.writeAll("true");
    }

    try writer.writeAll(",\"summary\":");

    if (summary_query) |query| {
        try writer.writeAll("{\"query\":");
        try appendJsonString(writer, query);
        try writer.writeByte('}');
    } else {
        try writer.writeAll("true");
    }

    try writer.writeAll(",\"extras\":{\"links\":");
    try writer.print("{d}", .{links});
    try writer.writeAll(",\"imageLinks\":");
    try writer.print("{d}", .{image_links});
    try writer.writeAll("},\"maxAgeHours\":");
    try writer.print("{d}", .{max_age_hours});

    if (subpages > 0) {
        try writer.writeAll(",\"subpages\":");
        try writer.print("{d}", .{subpages});
    }

    if (subpage_targets.items.len > 0) {
        try writer.writeAll(",\"subpageTarget\":");
        try appendStringArray(writer, subpage_targets.items);
    }

    try writer.writeByte('}');

    var response = try exaPost(allocator, client, api_key, "/contents", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

