fn runExaWebsets(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const query = try validateString(getObjectField(object, "query") orelse return error.InvalidArgument, "query");
    const count = try validateIntegerRange(
        getObjectField(object, "count") orelse return error.InvalidArgument,
        1,
        std.math.maxInt(i64),
    );

    const enrichment_description = try validateOptionalString(
        getObjectField(object, "enrichment_description") orelse return error.InvalidArgument,
    );

    const enrichment_format = try validateString(
        getObjectField(object, "enrichment_format") orelse return error.InvalidArgument,
        "enrichment_format",
    );

    const enrichment_options = try validateStringArray(
        allocator,
        getObjectField(object, "enrichment_options") orelse return error.InvalidArgument,
        150,
        null,
    );
    defer enrichment_options.deinit();

    if (std.mem.eql(u8, enrichment_format, "options")) {
        if (enrichment_description == null or enrichment_options.items.len == 0) {
            return error.InvalidArgument;
        }
    } else if (enrichment_options.items.len > 0) {
        return error.InvalidArgument;
    }

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const writer = body.writer();
    try writer.writeAll("{\"search\":{\"query\":");
    try appendJsonString(writer, query);
    try writer.writeAll(",\"count\":");
    try writer.print("{d}", .{count});
    try writer.writeAll("}");

    if (enrichment_description) |description| {
        try writer.writeAll(",\"enrichments\":[{\"description\":");
        try appendJsonString(writer, description);
        try writer.writeAll(",\"format\":");
        try appendJsonString(writer, enrichment_format);

        if (std.mem.eql(u8, enrichment_format, "options")) {
            try writer.writeAll(",\"options\":[");

            for (enrichment_options.items, 0..) |option, index| {
                if (index != 0) {
                    try writer.writeByte(',');
                }
                try writer.writeAll("{\"label\":");
                try appendJsonString(writer, option);
                try writer.writeByte('}');
            }

            try writer.writeByte(']');
        }

        try writer.writeAll("}]");
    }

    try writer.writeByte('}');

    var response = try exaPost(allocator, client, api_key, "/websets", body.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn urlEncodeComponent(allocator: Allocator, value: []const u8) ![]u8 {
    var output = std.ArrayList(u8).init(allocator);
    errdefer output.deinit();

    for (value) |character| {
        if (std.ascii.isAlphanumeric(character) or character == '' or character == '_' or character == '.' or character == '~') {
            try output.append(character);
        } else {
            try output.writer().print("%{X:0>2}", .{character});
        }
    }

    return output.toOwnedSlice();
}

fn runExaWebsetStatus(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const webset_id = try validateString(
        getObjectField(object, "webset_id") orelse return error.InvalidArgument,
        "webset_id",
    );

    const encoded_id = try urlEncodeComponent(allocator, webset_id);
    defer allocator.free(encoded_id);

    const path = try std.fmt.allocPrint(allocator, "/websets/{s}", .{encoded_id});
    defer allocator.free(path);

    var response = try exaGet(allocator, client, api_key, path);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runExaWebsetItems(
    allocator: Allocator,
    client: std.http.Client,
    api_key: []const u8,
    arguments: std.json.Value,
) ![]u8 {
    const object = switch (arguments) {
        .object => |object_value| object_value,
        else => return error.InvalidArgument,
    };

    const webset_id = try validateString(
        getObjectField(object, "webset_id") orelse return error.InvalidArgument,
        "webset_id",
    );

    const cursor_value = getObjectField(object, "cursor") orelse return error.InvalidArgument;
    const cursor = switch (cursor_value) {
        .string => |string| trimWhitespace(string),
        else => return error.InvalidArgument,
    };

    const limit = try validateIntegerRange(
        getObjectField(object, "limit") orelse return error.InvalidArgument,
        1,
        100,
    );

    const encoded_id = try urlEncodeComponent(allocator, webset_id);
    defer allocator.free(encoded_id);

    var path_builder = std.ArrayList(u8).init(allocator);
    defer path_builder.deinit();

    try path_builder.writer().print("/websets/{s}/items?limit={d}", .{
        encoded_id,
        limit,
    });

    if (cursor.len > 0) {
        const encoded_cursor = try urlEncodeComponent(allocator, cursor);
        defer allocator.free(encoded_cursor);

        try path_builder.writer().print("&cursor={s}", .{encoded_cursor});
    }

    var response = try exaGet(allocator, client, api_key, path_builder.items);
    defer response.deinit(allocator);

    try ensureSuccess(&response);
    return allocator.dupe(u8, response.body);
}

fn runTool(
    allocator: Allocator,
    client: std.http.Client,
    exa_api_key: []const u8,
    function_name: []const u8,
    arguments_text: []const u8,
) ![]u8 {
    var parsed_arguments = try parseJsonAlloc(allocator, arguments_text);
    defer parsed_arguments.deinit();

    if (std.mem.eql(u8, function_name, "exa_search")) {
        return runExaSearch(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_get_contents")) {
        return runExaGetContents(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_deep_search")) {
        return runExaDeepSearch(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_websets")) {
        return runExaWebsets(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_webset_status")) {
        return runExaWebsetStatus(allocator, client, exa_api_key, parsed_arguments.value);
    }

    if (std.mem.eql(u8, function_name, "exa_webset_items")) {
        return runExaWebsetItems(allocator, client, exa_api_key, parsed_arguments.value);
    }

    return error.UnsupportedTool;
}

